use tokio::{join, select, time::{sleep, Duration}};

async fn request_a() -> u32 { sleep(Duration::from_millis(200)).await; 1 }
async fn request_b() -> u32 { sleep(Duration::from_millis(300)).await; 2 }

#[tokio::main]
async fn main() {
    // join!: ambas em paralelo, mesmo task — total ~300ms, não 500ms
    let (a, b) = join!(request_a(), request_b());
    println!("join: {} {}", a, b);

    // select!: primeira a responder ganha (race / timeout)
    select! {
        r = request_a() => println!("a ganhou: {}", r),
        r = request_b() => println!("b ganhou: {}", r),
        _ = sleep(Duration::from_millis(100)) => println!("timeout"),
    }

    // spawn: fire-and-forget, nova task independente
    let handle = tokio::spawn(async { request_a().await });
    let v = handle.await.unwrap();
    println!("spawn: {}", v);
}

use axum::{Router, routing::get, extract::State, Json};
use serde::Serialize;
use std::sync::Arc;

#[derive(Clone)]
struct AppState { version: &'static str }

#[derive(Serialize)]
struct Health { ok: bool, version: String }

async fn health(State(s): State<Arc<AppState>>) -> Json<Health> {
    Json(Health { ok: true, version: s.version.to_string() })
}

#[tokio::main]
async fn main() {
    let state = Arc::new(AppState { version: "1.0.0" });
    let app = Router::new()
        .route("/health", get(health))
        .with_state(state);

    let listener = tokio::net::TcpListener::bind("0.0.0.0:3000").await.unwrap();
    axum::serve(listener, app).await.unwrap();
}

// canais mpsc com buffer fixo = backpressure automático
use tokio::sync::mpsc;

#[tokio::main]
async fn main() {
    let (tx, mut rx) = mpsc::channel::<u32>(100); // buffer 100

    // producer roda mais rápido que consumer? send().await bloqueia
    tokio::spawn(async move {
        for i in 0..10_000 {
            tx.send(i).await.unwrap(); // aplica backpressure
        }
    });

    while let Some(v) = rx.recv().await {
        processar(v).await;
    }
}
